create policy rv_private_session on public.chat_sessions as restrictive for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and exists(select 1 from public.assets a where a.id=chat_sessions.asset_id and a.organization_id=chat_sessions.organization_id and a.site_id=chat_sessions.site_id));
create policy rv_private_message on public.chat_messages as restrictive for all to authenticated using(exists(select 1 from public.chat_sessions s where s.id=chat_messages.session_id and s.user_id=auth.uid())) with check(user_id=auth.uid() and exists(select 1 from public.chat_sessions s where s.id=chat_messages.session_id and s.user_id=auth.uid()));
